(3729, 1563, 'Battery and Power', 'Up to 18 hours Apple TV app movie playback<br />\nUp to 15 hours wireless web<br />\n52.6-watt‑hour lithium‑polymer battery<br />\n30W USB-C Power Adapter (included with M2 and M3 with 8‑core GPU)<br />\n35W Dual USB-C Port Compact Power Adapter (included with M2 and M3 with 10-core GPU and 512GB storage, configurable with M2 and M3 with 8‑core GPU)<br />\nUSB-C to MagSafe 3 Cable', NULL, 6, 0.00, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2, NULL, NULL, '2025-02-21 10:33:46', '2025-02-21 10:33:46'),
(3730, 1563, 'Charging and Expansion', 'MagSafe 3 charging port<br />\n3.5 mm headphone jack<br />\nTwo Thunderbolt / USB 4 ports with support for:<br />\nCharging<br />\nDisplayPort<br />\nThunderbolt 3 (up to 40Gb/s)<br />\nUSB 4 (up to 40Gb/s)', NULL, 7, 0.00, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2, NULL, NULL, '2025-02-21 10:33:46', '2025-02-21 10:33:46'),
(3731, 1563, 'Keyboard & Touchpad', 'Backlit Magic Keyboard with:<br />\n78 (U.S.) or 79 (ISO) keys including 12 full-height function keys and 4 arrow keys in an inverted-T arrangement<br />\nTouch ID<br />\nAmbient light sensor<br />\nForce Touch trackpad for precise cursor control and pressure-sensing capabilities; enables Force clicks, accelerators, pressure-sensitive drawing, and multi-touch gestures', NULL, 8, 0.00, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2, NULL, NULL, '2025-02-21 10:33:46', '2025-02-21 10:33:46'),
